// Worker contract: generated by `delegate`, appended verbatim by every launcher.
// The delimited block is a routing marker, not an authentication secret.

import { join } from "node:path";
import { shellQuote } from "../config/config.ts";
import { isUuid } from "../util/misc.ts";
import type { Provider } from "./types.ts";

export const CONTRACT_VERSION = 1;

const OPEN_TAG = `<agentbus-contract version="${CONTRACT_VERSION}">`;
const CLOSE_TAG = "</agentbus-contract>";

export interface ContractInput {
  provider: Provider;
  requestId: string;
  workerId: string;
  parentId: string;
  cliCommand: string;
  stateDir: string;
  configPath: string;
}

type WorkerPaths = Pick<ContractInput, "cliCommand" | "stateDir" | "configPath" | "workerId">;

/** The full command prefix a worker runs: pinned CLI, store paths and identity. Several shell words. */
export function workerCommand(c: WorkerPaths): string {
  return `${c.cliCommand} --state-dir ${shellQuote(c.stateDir)} --config ${shellQuote(c.configPath)} --as ${c.workerId}`;
}

/** Private per-worker files: the executable and, for Claude, its hook settings. Kept by prune. */
export const workerDir = (stateDir: string, workerId: string): string => join(stateDir, "workers", workerId);

/**
 * Per-worker executable that runs `workerCommand` with the caller's arguments. A single path survives
 * being kept in a shell variable, which zsh and fish never word-split.
 */
export const workerBinPath = (stateDir: string, workerId: string): string =>
  join(workerDir(stateDir, workerId), "agentbus");

/** What a worker types: the executable's path, shell-quoted. */
export const workerBinCommand = (stateDir: string, workerId: string): string =>
  shellQuote(workerBinPath(stateDir, workerId));

export function workerBinScript(c: WorkerPaths): string {
  return `#!/bin/sh\n# Agentbus worker ${c.workerId}: fixed CLI, store paths and identity.\nexec ${workerCommand(c)} "$@"\n`;
}

export function renderContract(c: ContractInput): string {
  const ab = workerBinCommand(c.stateDir, c.workerId);
  const claude = c.provider === "claude";
  const askStep = claude
    ? [
        "   Run it in the background (run_in_background) and end your turn: it wakes you with the answer, printed",
        "   in full and already acknowledged. On exit 3 (timeout), or a follow-up instead of the answer, run the",
        "   same command again; it never posts twice. If you also lead your own Agentbus children, add --no-wait",
        "   and keep your single unfiltered wait instead.",
      ]
    : [
        "   Add --timeout 10m and run it in-turn; on exit 3 (timeout) run it again, it never posts twice. Or add",
        "   --no-wait and end your turn; the parent resumes this thread with the answer.",
      ];
  const followUpStep = claude
    ? "   Agentbus shows them to you after a tool call or when you try to end your turn."
    : "   Check for them with the read command from step 1 at each milestone.";
  return [
    OPEN_TAG,
    `agentbus-request: ${c.requestId}`,
    `agentbus-worker: ${c.workerId}`,
    `agentbus-parent: ${c.parentId}`,
    `agentbus-provider: ${c.provider}`,
    "",
    "You are a delegated worker. Agentbus is the durable mailbox between you and the agent that delegated",
    "this task (your parent); the mailbox copy of the request is the record. Run every Agentbus command",
    "through this single executable (CLI, store and identity are fixed; safe to keep in a shell variable):",
    `  ${ab}`,
    "If it is missing, type this out in full instead (zsh and fish do not word-split variables):",
    `  ${workerCommand(c)}`,
    "",
    "1. Read the request, then acknowledge it:",
    `     ${ab} read --correlation ${c.requestId}`,
    `     ${ab} ack ${c.requestId}`,
    "2. Optional progress, at real milestones only:",
    `     ${ab} reply ${c.requestId} --type progress --summary "<one line>" --file - <<'EOF'`,
    "     <details>",
    "     EOF",
    "3. A decision or blocker within this task's authorization goes to the parent, not the user (provider",
    "   permission prompts still belong to the user). Bundle decisions; one question at a time:",
    `     ${ab} ask --summary "<question>" --file - <<'EOF'`,
    "     <context and options>",
    "     EOF",
    ...askStep,
    "4. When finished, publish exactly one result. Finish all writes and delegated background edits first:",
    `     ${ab} finish --outcome <success|blocked|failed|unknown> --summary "<one line>" --file - <<'EOF'`,
    "     <what changed, verification performed, open decisions>",
    "     EOF",
    "   If it prints parent messages instead (exit 5), handle them, run the ack command it names and run",
    "   finish again. Then end your turn. `blocked` hands the task back; ask instead if the parent can help.",
    "5. Your parent may send follow-ups (new facts, changed scope) while you work.",
    followUpStep,
    "   Handle them within the task, then ack them.",
    "6. Never message the parent through provider-native channels; the mailbox is the record.",
    CLOSE_TAG,
  ].join("\n");
}

export interface ParsedContract {
  version: number;
  requestId: string;
  workerId: string;
  parentId: string | null;
  provider: string;
}

/**
 * Parses exactly one contract block whose tags start a line. Zero or multiple blocks, quoted blocks
 * (tags not at line start) and malformed headers yield null: they must never claim a session.
 */
export function parseContract(text: string): ParsedContract | null {
  if (!text.includes(OPEN_TAG)) return null;
  const lines = text.split(/\r?\n/);
  const opens: number[] = [];
  lines.forEach((line, i) => {
    if (line === OPEN_TAG) opens.push(i);
  });
  const anyOpenTag = lines.filter((l) => l.includes("<agentbus-contract")).length;
  if (opens.length !== 1 || anyOpenTag !== 1) return null;
  const start = opens[0]!;
  const end = lines.indexOf(CLOSE_TAG, start + 1);
  if (end < 0) return null;
  if (lines.filter((l) => l.includes(CLOSE_TAG)).length !== 1) return null;
  const header: Record<string, string> = {};
  for (let i = start + 1; i < end; i++) {
    const line = lines[i]!;
    if (line === "") break;
    const m = /^agentbus-([a-z]+): (.+)$/.exec(line);
    if (!m) return null;
    header[m[1]!] = m[2]!.trim();
  }
  const requestId = header.request;
  const workerId = header.worker;
  const provider = header.provider;
  if (!requestId || !workerId || !provider || !isUuid(requestId) || !isUuid(workerId)) return null;
  return { version: CONTRACT_VERSION, requestId, workerId, parentId: header.parent ?? null, provider };
}
